[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Global Aid Alliance — Together We Respond</title>
  <meta name="description" content="Global Aid Alliance is a humanitarian nonprofit dedicated to disaster relief, emergency assistance, and community resilience worldwide.">
  <style>
    /* ========== RESET & BASE ========== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
    body {
      font-family: 'Segoe UI', system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
      color: #333;
      background: #fff;
      line-height: 1.6;
      overflow-x: hidden;
    }
    a { color: inherit; text-decoration: none; }
    ul { list-style: none; }
    img { max-width: 100%; height: auto; display: block; }
    button { cursor: pointer; font-family: inherit; border: none; background: none; }
    :focus-visible { outline: 3px solid #1B3A5C; outline-offset: 2px; }

    /* ========== UTILITIES ========== */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }
    .btn {
      display: inline-flex; align-items: center; justify-content: center;
      padding: 14px 32px; border-radius: 6px; font-weight: 700; font-size: 1rem;
      transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
      text-align: center; line-height: 1.2;
    }
    .btn:active { transform: scale(0.97); }
    .btn-primary { background: #C41E3A; color: #fff; }
    .btn-primary:hover, .btn-primary:focus-visible { background: #a1182f; box-shadow: 0 4px 12px rgba(196,30,58,0.35); }
    .btn-secondary { background: #1B3A5C; color: #fff; }
    .btn-secondary:hover, .btn-secondary:focus-visible { background: #132b45; box-shadow: 0 4px 12px rgba(27,58,92,0.35); }
    .btn-outline { background: transparent; color: #fff; border: 2px solid #fff; }
    .btn-outline:hover, .btn-outline:focus-visible { background: rgba(255,255,255,0.12); }
    .btn-navy-outline { background: transparent; color: #1B3A5C; border: 2px solid #1B3A5C; }
    .btn-navy-outline:hover { background: #1B3A5C; color: #fff; }
    .section-label {
      text-transform: uppercase; letter-spacing: 2px; font-size: 0.8rem;
      color: #C41E3A; font-weight: 700; margin-bottom: 8px;
    }
    .section-title { font-size: clamp(1.75rem, 4vw, 2.5rem); color: #1B3A5C; font-weight: 800; line-height: 1.15; }

    /* ========== HEADER ========== */
    .header {
      position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
      background: #fff; border-bottom: 1px solid #e8e8e8;
      transition: box-shadow 0.3s;
    }
    .header.scrolled { box-shadow: 0 2px 16px rgba(0,0,0,0.08); }
    .header-inner {
      display: flex; align-items: center; justify-content: space-between;
      height: 72px; max-width: 1200px; margin: 0 auto; padding: 0 24px;
    }
    .logo { display: flex; align-items: center; gap: 10px; font-weight: 800; font-size: 1.15rem; color: #1B3A5C; }
    .logo-icon {
      width: 38px; height: 38px; background: #C41E3A; border-radius: 50%;
      display: flex; align-items: center; justify-content: center; color: #fff; font-size: 1.1rem;
    }
    .nav-desktop { display: flex; align-items: center; gap: 4px; }
    .nav-desktop a {
      padding: 8px 14px; font-size: 0.9rem; font-weight: 600; color: #333;
      border-radius: 4px; transition: color 0.2s, background 0.2s;
    }
    .nav-desktop a:hover { color: #C41E3A; background: #fdf2f4; }
    .nav-desktop .btn-donate-nav {
      background: #C41E3A; color: #fff; padding: 10px 22px; border-radius: 6px;
      font-weight: 700; margin-left: 8px; font-size: 0.9rem;
    }
    .nav-desktop .btn-donate-nav:hover { background: #a1182f; }
    .utility-links { display: flex; gap: 16px; font-size: 0.82rem; color: #666; }
    .utility-links a:hover { color: #C41E3A; }
    .hamburger {
      display: none; flex-direction: column; gap: 5px; padding: 8px;
      width: 44px; height: 44px; align-items: center; justify-content: center;
    }
    .hamburger span { display: block; width: 24px; height: 2px; background: #1B3A5C; border-radius: 2px; transition: transform 0.3s, opacity 0.3s; }

    /* Mobile nav */
    .mobile-nav {
      display: none; position: fixed; top: 72px; left: 0; right: 0; bottom: 0;
      background: #fff; z-index: 999; padding: 24px; overflow-y: auto;
      transform: translateX(100%); transition: transform 0.35s ease;
    }
    .mobile-nav.open { transform: translateX(0); display: block; }
    .mobile-nav a {
      display: block; padding: 16px 0; font-size: 1.1rem; font-weight: 600;
      color: #1B3A5C; border-bottom: 1px solid #eee;
    }
    .mobile-nav a:hover { color: #C41E3A; }
    .mobile-nav .btn { width: 100%; margin-top: 20px; }

    /* Hamburger active state */
    .hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
    .hamburger.active span:nth-child(2) { opacity: 0; }
    .hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

    /* ========== HERO ========== */
    .hero {
      margin-top: 72px; position: relative; overflow: hidden;
      background: linear-gradient(135deg, #1B3A5C 0%, #0d1f33 100%);
      color: #fff; min-height: 600px; display: flex; align-items: center;
    }
    .hero-bg {
      position: absolute; inset: 0; opacity: 0.18;
      background-image: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 600"><rect fill="%231B3A5C" width="1200" height="600"/><circle cx="200" cy="300" r="250" fill="%23C41E3A" opacity="0.2"/><circle cx="900" cy="150" r="180" fill="%23C41E3A" opacity="0.15"/><circle cx="600" cy="450" r="200" fill="%23fff" opacity="0.05"/></svg>');
      background-size: cover; background-position: center;
    }
    .hero-inner {
      position: relative; z-index: 1; max-width: 1200px; margin: 0 auto;
      padding: 80px 24px; display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
    }
    .hero-text h1 { font-size: clamp(2.2rem, 5vw, 3.5rem); font-weight: 900; line-height: 1.08; margin-bottom: 20px; }
    .hero-text p { font-size: 1.15rem; line-height: 1.7; opacity: 0.9; margin-bottom: 32px; max-width: 520px; }
    .hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }
    .hero-image {
      display: flex; align-items: center; justify-content: center;
      position: relative;
    }
    .hero-image-placeholder {
      width: 100%; max-width: 460px; aspect-ratio: 4/3; border-radius: 16px;
      background: linear-gradient(135deg, rgba(196,30,58,0.25), rgba(27,58,92,0.35));
      display: flex; align-items: center; justify-content: center;
      font-size: 1rem; color: rgba(255,255,255,0.5); text-align: center;
      padding: 20px; border: 2px solid rgba(255,255,255,0.1);
    }

    /* ========== MISSION ========== */
    .mission { padding: 100px 0; background: #fafafa; }
    .mission-grid {
      display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
    }
    .mission-badge {
      display: inline-flex; align-items: center; gap: 8px;
      background: #fdf2f4; color: #C41E3A; padding: 8px 16px; border-radius: 20px;
      font-weight: 700; font-size: 0.85rem; margin-bottom: 16px;
    }
    .mission-badge::before { content: ''; width: 8px; height: 8px; background: #C41E3A; border-radius: 50%; }
    .mission-text h2 { font-size: clamp(1.75rem, 3.5vw, 2.25rem); color: #1B3A5C; font-weight: 800; margin-bottom: 20px; line-height: 1.2; }
    .mission-text p { font-size: 1.05rem; color: #555; line-height: 1.8; margin-bottom: 16px; }
    .mission-image {
      width: 100%; aspect-ratio: 4/3; border-radius: 16px;
      background: linear-gradient(135deg, #e8eef4, #dce5ef);
      display: flex; align-items: center; justify-content: center;
      color: #999; font-size: 0.95rem;
    }

    /* ========== IMPACT STATS ========== */
    .impact { padding: 80px 0; background: #1B3A5C; color: #fff; }
    .impact-header { text-align: center; margin-bottom: 60px; }
    .impact-header .section-label { color: #f5a0ab; }
    .impact-header .section-title { color: #fff; }
    .impact-grid {
      display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px;
    }
    .stat-card {
      text-align: center; padding: 40px 20px; border-radius: 12px;
      background: rgba(255,255,255,0.07); border: 1px solid rgba(255,255,255,0.1);
      transition: background 0.3s;
    }
    .stat-card:hover { background: rgba(255,255,255,0.12); }
    .stat-number {
      font-size: clamp(2rem, 4vw, 3rem); font-weight: 900; color: #fff;
      margin-bottom: 4px; line-height: 1.1;
    }
    .stat-number .accent { color: #f5a0ab; }
    .stat-label { font-size: 0.95rem; opacity: 0.85; font-weight: 500; }
    .stat-caption { margin-top: 48px; text-align: center; font-size: 1rem; opacity: 0.75; max-width: 600px; margin-left: auto; margin-right: auto; line-height: 1.7; }

    /* ========== PROGRAMS ========== */
    .programs { padding: 100px 0; background: #fff; }
    .programs-header { text-align: center; margin-bottom: 48px; }
    .accordion { max-width: 800px; margin: 0 auto; }
    .accordion-item { border-bottom: 1px solid #e8e8e8; }
    .accordion-trigger {
      width: 100%; display: flex; align-items: center; justify-content: space-between;
      padding: 24px 0; font-size: 1.15rem; font-weight: 700; color: #1B3A5C;
      text-align: left; transition: color 0.2s;
    }
    .accordion-trigger:hover { color: #C41E3A; }
    .accordion-icon {
      width: 28px; height: 28px; border-radius: 50%; background: #f0f4f8;
      display: flex; align-items: center; justify-content: center;
      font-size: 1.2rem; transition: transform 0.3s, background 0.3s; flex-shrink: 0;
    }
    .accordion-trigger[aria-expanded="true"] .accordion-icon { transform: rotate(45deg); background: #fdf2f4; color: #C41E3A; }
    .accordion-panel {
      overflow: hidden; max-height: 0; transition: max-height 0.4s ease, padding 0.3s;
    }
    .accordion-panel.open { max-height: 300px; padding-bottom: 24px; }
    .accordion-panel p { color: #555; font-size: 1rem; line-height: 1.8; padding-right: 40px; }

    /* ========== GET INVOLVED ========== */
    .involved { padding: 100px 0; background: #fafafa; }
    .involved-header { text-align: center; margin-bottom: 56px; }
    .involved-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
    .involved-card {
      background: #fff; border-radius: 12px; padding: 40px 32px;
      border: 1px solid #e8e8e8; transition: transform 0.2s, box-shadow 0.2s;
    }
    .involved-card:hover { transform: translateY(-4px); box-shadow: 0 12px 32px rgba(0,0,0,0.08); }
    .involved-icon {
      width: 56px; height: 56px; border-radius: 12px; margin-bottom: 20px;
      display: flex; align-items: center; justify-content: center; font-size: 1.5rem;
    }
    .involved-icon.red { background: #fdf2f4; color: #C41E3A; }
    .involved-icon.navy { background: #e8eef4; color: #1B3A5C; }
    .involved-icon.warm { background: #fef6e6; color: #b87d1b; }
    .involved-card h3 { font-size: 1.25rem; font-weight: 800; color: #1B3A5C; margin-bottom: 12px; }
    .involved-card p { font-size: 0.95rem; color: #666; line-height: 1.7; margin-bottom: 24px; }

    /* ========== NEWS ========== */
    .news { padding: 100px 0; background: #fff; }
    .news-header { display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 48px; flex-wrap: wrap; gap: 16px; }
    .news-controls { display: flex; gap: 8px; }
    .news-controls button {
      width: 44px; height: 44px; border-radius: 50%; border: 2px solid #ddd;
      display: flex; align-items: center; justify-content: center;
      font-size: 1.2rem; color: #1B3A5C; transition: all 0.2s;
    }
    .news-controls button:hover { border-color: #1B3A5C; background: #f0f4f8; }
    .news-carousel { overflow: hidden; position: relative; }
    .news-track {
      display: flex; gap: 28px; transition: transform 0.5s ease;
    }
    .news-card {
      min-width: calc(33.333% - 19px); flex-shrink: 0;
      border-radius: 12px; overflow: hidden; border: 1px solid #e8e8e8;
      background: #fff; transition: box-shadow 0.2s;
    }
    .news-card:hover { box-shadow: 0 8px 24px rgba(0,0,0,0.08); }
    .news-card-img {
      width: 100%; aspect-ratio: 16/9; background: #e8eef4;
      display: flex; align-items: center; justify-content: center;
      color: #aaa; font-size: 0.85rem;
    }
    .news-card-body { padding: 24px; }
    .news-card-tag {
      display: inline-block; font-size: 0.75rem; font-weight: 700;
      text-transform: uppercase; letter-spacing: 1px; color: #C41E3A;
      margin-bottom: 8px;
    }
    .news-card-body h3 { font-size: 1.1rem; font-weight: 700; color: #1B3A5C; margin-bottom: 10px; line-height: 1.35; }
    .news-card-body p { font-size: 0.9rem; color: #666; line-height: 1.65; }

    /* ========== DONATE CTA ========== */
    .donate-cta {
      padding: 100px 0;
      background: linear-gradient(135deg, #C41E3A 0%, #9a1630 100%);
      color: #fff;
    }
    .donate-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: start; }
    .donate-text h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); font-weight: 900; margin-bottom: 16px; }
    .donate-text p { font-size: 1.05rem; line-height: 1.7; opacity: 0.9; margin-bottom: 12px; }
    .donate-text .efficiency { font-size: 1rem; opacity: 0.8; font-style: italic; }
    .impact-table { width: 100%; border-collapse: collapse; margin-bottom: 32px; }
    .impact-table th { text-align: left; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 1px; opacity: 0.7; padding: 12px 0; border-bottom: 1px solid rgba(255,255,255,0.2); }
    .impact-table td { padding: 16px 0; border-bottom: 1px solid rgba(255,255,255,0.1); font-size: 1rem; }
    .impact-table td:first-child { font-weight: 800; font-size: 1.15rem; white-space: nowrap; padding-right: 24px; }
    .impact-table td:last-child { opacity: 0.9; }

    /* ========== DONATE MODAL ========== */
    .modal-overlay {
      display: none; position: fixed; inset: 0; z-index: 2000;
      background: rgba(0,0,0,0.55); align-items: center; justify-content: center;
      padding: 24px; opacity: 0; transition: opacity 0.3s;
    }
    .modal-overlay.open { display: flex; opacity: 1; }
    .modal {
      background: #fff; border-radius: 16px; max-width: 520px; width: 100%;
      max-height: 90vh; overflow-y: auto; color: #333;
      transform: translateY(20px); transition: transform 0.3s;
    }
    .modal-overlay.open .modal { transform: translateY(0); }
    .modal-header {
      display: flex; align-items: center; justify-content: space-between;
      padding: 24px 32px; border-bottom: 1px solid #eee;
    }
    .modal-header h2 { font-size: 1.35rem; font-weight: 800; color: #1B3A5C; }
    .modal-close {
      width: 40px; height: 40px; border-radius: 50%; display: flex;
      align-items: center; justify-content: center; font-size: 1.5rem;
      color: #666; transition: background 0.2s;
    }
    .modal-close:hover { background: #f0f0f0; }
    .modal-body { padding: 32px; }
    .amount-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 20px; }
    .amount-btn {
      padding: 16px 8px; border: 2px solid #e0e0e0; border-radius: 8px;
      font-weight: 700; font-size: 1.1rem; color: #1B3A5C; text-align: center;
      transition: all 0.2s; background: #fff;
    }
    .amount-btn:hover { border-color: #C41E3A; color: #C41E3A; }
    .amount-btn.selected { border-color: #C41E3A; background: #fdf2f4; color: #C41E3A; }
    .amount-btn .impact { display: block; font-size: 0.7rem; font-weight: 500; color: #999; margin-top: 4px; }
    .custom-amount { margin-bottom: 24px; }
    .custom-amount label { display: block; font-weight: 600; font-size: 0.9rem; margin-bottom: 8px; color: #555; }
    .custom-amount input {
      width: 100%; padding: 14px 16px; border: 2px solid #e0e0e0; border-radius: 8px;
      font-size: 1rem; font-weight: 600; color: #1B3A5C; transition: border-color 0.2s;
    }
    .custom-amount input:focus { border-color: #C41E3A; outline: none; }
    .custom-amount input::placeholder { color: #bbb; font-weight: 400; }
    .frequency-toggle { display: flex; gap: 0; margin-bottom: 24px; border-radius: 8px; overflow: hidden; border: 2px solid #e0e0e0; }
    .frequency-btn {
      flex: 1; padding: 12px; font-weight: 700; font-size: 0.9rem;
      text-align: center; color: #666; transition: all 0.2s; background: #fff;
    }
    .frequency-btn.selected { background: #1B3A5C; color: #fff; }
    .modal .btn-primary { width: 100%; padding: 16px; font-size: 1.1rem; }
    .modal-footer { padding: 16px 32px 24px; text-align: center; font-size: 0.82rem; color: #999; }

    /* ========== FOOTER ========== */
    .footer { background: #0d1f33; color: rgba(255,255,255,0.7); padding: 64px 0 0; }
    .footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 32px; margin-bottom: 48px; }
    .footer-brand p { font-size: 0.9rem; line-height: 1.7; margin-top: 16px; max-width: 280px; }
    .footer h4 { color: #fff; font-size: 0.85rem; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 16px; }
    .footer ul li { margin-bottom: 10px; }
    .footer ul a { font-size: 0.9rem; transition: color 0.2s; }
    .footer ul a:hover { color: #fff; }
    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1); padding: 24px 0;
      display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 16px;
    }
    .footer-bottom p { font-size: 0.82rem; }
    .social-links { display: flex; gap: 16px; }
    .social-links a {
      width: 40px; height: 40px; border-radius: 50%; background: rgba(255,255,255,0.08);
      display: flex; align-items: center; justify-content: center; font-size: 0.85rem;
      transition: background 0.2s;
    }
    .social-links a:hover { background: #C41E3A; color: #fff; }

    /* ========== RESPONSIVE ========== */
    @media (max-width: 1024px) {
      .hero-inner { grid-template-columns: 1fr; text-align: center; padding: 60px 24px; }
      .hero-text p { margin-left: auto; margin-right: auto; }
      .hero-actions { justify-content: center; }
      .hero-image { display: none; }
      .mission-grid { grid-template-columns: 1fr; }
      .mission-image { order: -1; }
      .impact-grid { grid-template-columns: repeat(2, 1fr); }
      .involved-grid { grid-template-columns: 1fr 1fr; }
      .news-card { min-width: calc(50% - 14px); }
      .donate-grid { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: 1fr 1fr; }
    }
    @media (max-width: 768px) {
      .nav-desktop, .utility-links { display: none; }
      .hamburger { display: flex; }
      .mobile-nav { display: none; }
      .mobile-nav.open { display: block; transform: translateX(0); }
      .hero { min-height: auto; }
      .hero-inner { padding: 48px 24px; }
      .impact-grid { grid-template-columns: 1fr 1fr; gap: 16px; }
      .stat-card { padding: 28px 16px; }
      .involved-grid { grid-template-columns: 1fr; }
      .news-card { min-width: 100%; }
      .amount-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: 1fr; gap: 24px; }
      .footer-bottom { flex-direction: column; text-align: center; }
    }
  </style>
</head>
<body>

  <!-- ========== HEADER ========== -->
  <header class="header" id="header" role="banner">
    <div class="header-inner">
      <a href="#" class="logo" aria-label="Global Aid Alliance Home">
        <span class="logo-icon" aria-hidden="true">+</span>
        Global Aid Alliance
      </a>
      <nav class="nav-desktop" aria-label="Primary navigation">
        <a href="#mission">About Us</a>
        <a href="#programs">Disaster Relief</a>
        <a href="#programs">Programs &amp; Services</a>
        <a href="#involved">Volunteer</a>
        <a href="#footer">Find Local Chapter</a>
        <button class="btn-donate-nav" onclick="openDonateModal()">Donate</button>
      </nav>
      <div class="utility-links">
        <a href="#">Sign In</a>
        <a href="#">Contact Us</a>
        <a href="#">Espa&ntilde;ol</a>
      </div>
      <button class="hamburger" id="hamburger" aria-label="Toggle menu" aria-expanded="false" aria-controls="mobile-nav">
        <span></span><span></span><span></span>
      </button>
    </div>
  </header>

  <!-- Mobile Navigation -->
  <nav class="mobile-nav" id="mobile-nav" aria-label="Mobile navigation">
    <a href="#mission" onclick="closeMobileNav()">About Us</a>
    <a href="#programs" onclick="closeMobileNav()">Disaster Relief</a>
    <a href="#programs" onclick="closeMobileNav()">Programs &amp; Services</a>
    <a href="#involved" onclick="closeMobileNav()">Volunteer</a>
    <a href="#footer" onclick="closeMobileNav()">Find Local Chapter</a>
    <a href="#" onclick="closeMobileNav()">Sign In</a>
    <a href="#" onclick="closeMobileNav()">Contact Us</a>
    <a href="#" onclick="closeMobileNav()">Espa&ntilde;ol</a>
    <button class="btn btn-primary" onclick="closeMobileNav(); openDonateModal();" style="margin-top:24px;">Donate Now</button>
  </nav>

  <!-- ========== HERO ========== -->
  <section class="hero" id="hero">
    <div class="hero-bg" aria-hidden="true"></div>
