  <script>
    // === Header scroll shadow ===
    const header = document.getElementById('header');
    window.addEventListener('scroll', () => {
      header.classList.toggle('scrolled', window.scrollY > 10);
    }, { passive: true });

    // === Mobile menu ===
    const hamburger = document.getElementById('hamburger');
    const mobileNav = document.getElementById('mobile-nav');

    hamburger.addEventListener('click', () => {
      const isOpen = mobileNav.classList.toggle('open');
      hamburger.classList.toggle('active', isOpen);
      hamburger.setAttribute('aria-expanded', isOpen);
      document.body.style.overflow = isOpen ? 'hidden' : '';
    });

    function closeMobileNav() {
      mobileNav.classList.remove('open');
      hamburger.classList.remove('active');
      hamburger.setAttribute('aria-expanded', 'false');
      document.body.style.overflow = '';
    }

    // === Donate modal ===
    const modal = document.getElementById('donate-modal');
    let selectedAmount = 100;

    function openDonateModal() {
      modal.classList.add('open');
      document.body.style.overflow = 'hidden';
      modal.querySelector('.amount-btn').focus();
    }

    function closeDonateModal() {
      modal.classList.remove('open');
      document.body.style.overflow = '';
    }

    modal.addEventListener('click', (e) => {
      if (e.target === modal) closeDonateModal();
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && modal.classList.contains('open')) closeDonateModal();
    });

    function selectAmount(btn) {
      document.querySelectorAll('.amount-btn').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      selectedAmount = parseInt(btn.dataset.amount);
      document.getElementById('custom-amount-input').value = '';
    }

    function clearPresetAmount() {
      document.querySelectorAll('.amount-btn').forEach(b => b.classList.remove('selected'));
    }

    function selectFrequency(btn) {
      document.querySelectorAll('.frequency-btn').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
    }

    function submitDonation() {
      const customVal = document.getElementById('custom-amount-input').value;
      const amount = customVal ? parseInt(customVal) : selectedAmount;
      const freq = document.querySelector('.frequency-btn.selected').textContent.trim().toLowerCase();
      alert(`Thank you for your ${freq} donation of $${amount}! In a live site, this would proceed to a secure payment processor.`);
    }

    // === Accordion ===
    document.querySelectorAll('.accordion-trigger').forEach(trigger => {
      trigger.addEventListener('click', () => {
        const panel = document.getElementById(trigger.getAttribute('aria-controls'));
        const isOpen = trigger.getAttribute('aria-expanded') === 'true';

        // Close all
        document.querySelectorAll('.accordion-trigger').forEach(t => {
          t.setAttribute('aria-expanded', 'false');
          document.getElementById(t.getAttribute('aria-controls')).classList.remove('open');
        });

        // Toggle clicked
        if (!isOpen) {
          trigger.setAttribute('aria-expanded', 'true');
          panel.classList.add('open');
        }
      });
    });

    // === News carousel ===
    const track = document.getElementById('news-track');
    const cards = track.querySelectorAll('.news-card');
    let currentSlide = 0;

    function getVisibleCards() {
      if (window.innerWidth <= 768) return 1;
      if (window.innerWidth <= 1024) return 2;
      return 3;
    }

    function getMaxSlide() {
      return Math.max(0, cards.length - getVisibleCards());
    }

    function updateCarousel() {
      const visible = getVisibleCards();
      const gap = 28;
      const cardWidth = track.parentElement.offsetWidth / visible - (gap * (visible - 1) / visible);
      cards.forEach(c => c.style.minWidth = cardWidth + 'px');
      const offset = currentSlide * (cardWidth + gap);
      track.style.transform = `translateX(-${offset}px)`;
    }

    document.getElementById('news-prev').addEventListener('click', () => {
      currentSlide = Math.max(0, currentSlide - 1);
      updateCarousel();
    });

    document.getElementById('news-next').addEventListener('click', () => {
      currentSlide = Math.min(getMaxSlide(), currentSlide + 1);
      updateCarousel();
    });

    window.addEventListener('resize', () => {
      currentSlide = Math.min(currentSlide, getMaxSlide());
      updateCarousel();
    });

    updateCarousel();

    // === Animated counters ===
    function animateCounters() {
      const counters = document.querySelectorAll('.counter');
      counters.forEach(counter => {
        const target = parseInt(counter.dataset.target);
        const duration = 2000;
        const start = performance.now();

        function update(now) {
          const elapsed = now - start;
          const progress = Math.min(elapsed / duration, 1);
          const eased = 1 - Math.pow(1 - progress, 3); // ease-out cubic
          counter.textContent = Math.round(eased * target);
          if (progress < 1) requestAnimationFrame(update);
        }

        requestAnimationFrame(update);
      });
    }

    // Intersection Observer for counters
    const statsSection = document.getElementById('impact');
    let countersAnimated = false;
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting && !countersAnimated) {
          countersAnimated = true;
          animateCounters();
        }
      });
    }, { threshold: 0.3 });
    observer.observe(statsSection);
  </script>
